using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Ara {
 public static class ReplicaTests {
  static void Assert(bool ok,string why){if(!ok)throw new Exception(why);}
  static State New(){var s=State.New();var d=s.GetDay(new DateTime(2026,10,16));d.Wake=d.Wake.Date.AddHours(8);GridEngine.Ensure(s,d);return ReplicaSync.Slice(s,d.Date);}
  static State Edit(State baseline,int first,int count,string op="score",decimal score=3){var s=Store.Clone(baseline);var d=s.Days[0];var before=Store.Clone(s);PhoneEditing.Apply(s,d,new PhoneCommand{date=d.Date,lane=1,first=first,last=first+count-1,op=op,score=score,category="학습",name="공부"});BlockTools.Merge(d.Records);PlanHistory.Advance(before,before.Days[0],s,d);GridEngine.Build(s,d);return s;}
  public static void Run(Action<string,Action> check,string dir){
   check("replica: independent offline and PC records merge without loss",()=>{var b=New();var l=Edit(b,60,3);var c=Edit(b,72,2,"score",5);var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date);Assert(GridEngine.Total(m.Days[0])==19&&m.Days[0].Records.Sum(x=>x.Count)==5,"both edits preserved");});
   check("replica: replay after lost response is idempotent",()=>{var b=New();var l=Edit(b,60,3);var c=Edit(b,72,2);var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date);var twice=ReplicaSync.Merge(b,l,m,b.Days[0].Date);Assert(GridEngine.Total(twice.Days[0])==15&&twice.Days[0].Records.Sum(x=>x.Count)==5,"not duplicated");});
   check("replica: same cell edited differently conflicts and changes no input",()=>{var b=New();var l=Edit(b,60,3);var c=Edit(b,60,3,"score",5);string facts=JsonMap.Write(c);bool conflict=false;try{ReplicaSync.Merge(b,l,c,b.Days[0].Date);}catch(SyncConflict){conflict=true;}Assert(conflict&&JsonMap.Write(c)==facts,"both sides retained");});
   check("replica: disjoint cell edits inside a block preserve distinct scores",()=>{var b=Edit(New(),60,6,"score",1);var l=Edit(b,60,2,"score",4);var c=Edit(b,64,2,"score",5);var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date);Assert(GridEngine.Total(m.Days[0])==20,"cell merge");GridEngine.Validate(m.Days[0]);});
   check("replica: same source moved to different places conflicts",()=>{var b=Edit(New(),60,3);var l=Store.Clone(b);var c=Store.Clone(b);l.Days[0].Records[0].Start=l.Days[0].Records[0].Start.AddHours(1);c.Days[0].Records[0].Start=c.Days[0].Records[0].Start.AddHours(2);bool conflict=false;try{ReplicaSync.Merge(b,l,c,b.Days[0].Date);}catch(SyncConflict){conflict=true;}Assert(conflict,"no duplicate moved record");});
   check("replica: merge keeps other dates and PC notification history",()=>{var b=New();var l=Edit(b,60,1);var c=Store.Clone(b);c.Days[0].Notified.Add("delivered");c.GetDay(new DateTime(2026,10,15)).Note="other date";var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date);Assert(m.Days.Count==2&&m.Days[0].Note=="other date"&&m.GetDay(new DateTime(2026,10,16)).Notified.Contains("delivered"),"other date and delivered markers");});
   check("replica: different category additions merge and deleted categories stay archived",()=>{var b=New();var l=Store.Clone(b);var c=Store.Clone(b);CategoryCatalog.Save(l,"c_"+new string('a',32),"독서","#B8D8EE",false,0);CategoryCatalog.Save(c,"c_"+new string('b',32),"산책","#B9DDC7",false,0);var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date);Assert(CategoryCatalog.Keys(m).Length==12,"both catalog entries");var d=m.Days[0];PhoneEditing.Apply(m,d,new PhoneCommand{op="category-delete",id="학습",first=0,last=0,lane=1});Assert(!CategoryCatalog.Keys(m).Contains("학습")&&CategoryCatalog.Label(m.CategorySettings,"학습")=="학습","archive retains label");});
   check("replica: category deletion preserves recorded scores and historical color",()=>{var s=Edit(New(),60,3);var d=s.Days[0];d.Records[0].Category="학습";string color=s.CategorySettings.Find(x=>x.name=="학습").color;PhoneEditing.Apply(s,d,new PhoneCommand{op="category-delete",id="학습",first=0,last=0,lane=1});CategoryCatalog.Ensure(s);Engine.Validate(s);Assert(d.Records.Count==1&&GridEngine.Total(d)==9&&s.CategorySettings.Find(x=>x.name=="학습").color==color&&!CategoryCatalog.Keys(s).Contains("학습"),"history unchanged and no resurrection");});
   check("replica: explicit local resolution preserves unrelated PC dates",()=>{var b=New();var l=Edit(b,60,3);var c=Edit(b,60,3,"score",5);c.GetDay(new DateTime(2026,10,15)).Note="keep";var m=ReplicaSync.Merge(b,l,c,b.Days[0].Date,true);Assert(GridEngine.Total(m.GetDay(new DateTime(2026,10,16)))==9&&m.GetDay(new DateTime(2026,10,15)).Note=="keep","scoped resolution");});
   check("replica: transport snapshot round trip validates persistent state",()=>{var s=Edit(New(),60,3);var reply=ReplicaSync.Reply(s,s.Days[0].Date);var decoded=PhoneCodec.Read<State>(System.Text.Encoding.UTF8.GetBytes(reply.state));Engine.Validate(decoded);Assert(decoded.Days.Count==1&&decoded.RemoteReceipts.Count==0&&reply.view.total==9,"clean durable slice");});
  }
 }
}
